INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11903$nota-0004$m11903$, $m11904$Training and Racing with a Power Meter.pdf$m11904$, $m11905$30$m11905$, $m11906$Andrew says it best: Training is testing; testing is training. Treat every training session as an opportunity to build toward a peak performance.$m11906$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11907$nota-0004$m11907$, $m11908$Training and Racing with a Power Meter.pdf$m11908$, $m11909$30$m11909$, $m11910$A power meter allows you to test your fitness on a periodic basis, such as every month, so you can quantitatively see where you have made improvements and where you still need work.$m11910$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11911$nota-0017$m11911$, $m11912$Training and Racing with a Power Meter.pdf$m11912$, $m11913$49$m11913$, $m11914$Make it a habit to use the lap button on your power-meter head unit. Simply touch the lap button just before you begin the interval, and then again when you stop the interval.$m11914$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11915$nota-0017$m11915$, $m11916$Training and Racing with a Power Meter.pdf$m11916$, $m11917$49$m11917$, $m11918$When doing intervals such as micro-bursts or crisscross efforts... you will want to mark only the beginning and end of the larger interval.$m11918$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11919$nota-0020$m11919$, $m11920$Training and Racing with a Power Meter.pdf$m11920$, $m11921$58$m11921$, $m11922$Be sure to do the same warm-up... The warm-up and recovery intervals throughout the test should be at about 65 percent of your functional threshold power... When you begin the 5-minute all-out effort, punch it and hold it!$m11922$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11923$nota-0020$m11923$, $m11924$Training and Racing with a Power Meter.pdf$m11924$, $m11925$59$m11925$, $m11926$figure out what your average power was for the entire 20-minute effort. Take this number and subtract 5 percent from it as a general rule... if you average 305 watts for the 20-minute time trial, you would calculate that 305 × 0.05 = 15.25, and 305 – 15.25 = 290. Thus, your functional threshold power is estimated to be 290 watts.$m11926$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11927$nota-0020$m11927$, $m11928$Training and Racing with a Power Meter.pdf$m11928$, $m11929$59$m11929$, $m11930$Some riders with a higher anaerobic capacity might have to subtract 7 or more percent, while riders that are purely aerobic might need to only subtract 2–3 percent.$m11930$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m11931$nota-0020$m11931$, $m11932$nota-0019$m11932$, $m11933$pre-requisito$m11933$, $m11934$o protocolo estima o FTP definido na nota-0019$m11934$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11935$nota-0021$m11935$, $m11936$Training and Racing with a Power Meter.pdf$m11936$, $m11937$52$m11937$, $m11938$It would be a good idea to repeat this threshold test every six to eight weeks in order to assess your fitness, track performance changes, and decide whether to make changes to your training program based on the results.$m11938$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11939$nota-0021$m11939$, $m11940$Training and Racing with a Power Meter.pdf$m11940$, $m11941$60$m11941$, $m11942$In general, assessing FTP six to eight times a year... is probably sufficient.$m11942$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11943$nota-0024$m11943$, $m11944$Training and Racing with a Power Meter.pdf$m11944$, $m11945$62$m11945$, $m11946$The values used in Table 3.1 for perceived exertion are from Gunnar Borg's 10-point category ratio scale (see Table 3.3), not the original 20-point scale that is more commonly used.$m11946$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11947$nota-0024$m11947$, $m11948$Training and Racing with a Power Meter.pdf$m11948$, $m11949$63$m11949$, $m11950$TABLE 3.3 Perceived Exertion Scale — 0 Nothing at all, 0.5 Extremely weak, 1 Very weak, 2 Weak (light), 3 Moderate, 4 Somewhat strong, 5 Strong (heavy), 6-7 Very strong, 8-10 Extremely strong, • Maximal$m11950$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m11951$nota-0024$m11951$, $m11952$nota-0022$m11952$, $m11953$complementa$m11953$, $m11954$é a escala usada na coluna RPE da Tabela 3.1 (nota-0022)$m11954$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11955$nota-0025$m11955$, $m11956$Training and Racing with a Power Meter.pdf$m11956$, $m11957$54$m11957$, $m11958$Power Frequency Distribution Charts. A good estimate of FTP can often be obtained by simply uploading all of your training data into your power-meter software and then examining the power frequency distribution chart... there will often be a rather noticeable drop-off above this point.$m11958$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11959$nota-0025$m11959$, $m11960$Training and Racing with a Power Meter.pdf$m11960$, $m11961$55$m11961$, $m11962$Routine Steady Power... look for places where your power is quasi-constant for some minutes at a time.$m11962$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11963$nota-0025$m11963$, $m11964$Training and Racing with a Power Meter.pdf$m11964$, $m11965$56$m11965$, $m11966$Normalized Power... examine your Normalized Power... during hard mass-start races of approximately one hour.$m11966$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11967$nota-0025$m11967$, $m11968$Training and Racing with a Power Meter.pdf$m11968$, $m11969$56$m11969$, $m11970$One-Hour Time Trial. Since, by definition, the best measure of performance is performance itself, the most direct estimate of your FTP will be obtained by simply doing a one-hour time trial.$m11970$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m11971$nota-0025$m11971$, $m11972$nota-0020$m11972$, $m11973$alternativa-a$m11973$, $m11974$métodos alternativos ao teste de campo de 20 minutos (nota-0020) para chegar numa estimativa de FTP$m11974$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11975$nota-0031$m11975$, $m11976$Training and Racing with a Power Meter.pdf$m11976$, $m11977$69$m11977$, $m11978$TABLE 4.1 Power Profile Chart — Maximal Power Output (in W/kg) — 5 s | 1 min | 5 min | FT — Men and Women, categorias: World class, Exceptional, Excellent, Very good, Good, Moderate, Fair, Novice 2, Novice 1$m11978$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m11979$nota-0031$m11979$, $m11980$Training and Racing with a Power Meter.pdf$m11980$, $m11981$71$m11981$, $m11982$a world-class match sprinter can produce over 23 watts per kilogram (W/kg) in a 5-second sprint, whereas a novice might produce only 10 to 12.5 W/kg.$m11982$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m11983$nota-0031$m11983$, $m11984$nota-0032$m11984$, $m11985$pre-requisito$m11985$, $m11986$usa as 4 durações-índice (5s, 1min, 5min, FTP) definidas na nota-0032$m11986$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m11987$nota-0031$m11987$, $m11988$nota-0033$m11988$, $m11989$pre-requisito$m11989$, $m11990$os valores da tabela são normalizados por peso (W/kg), conceito da nota-0033$m11990$)
